#include <stdlib.h>
#include "check.h"
#include "srcinfo.h"

static const char *SI =
	"# Generated by makepkg\n"
	"pkgbase = foo\n"
	"\tpkgdesc = Basis-Beschreibung\n"
	"\tpkgver = 1.2.3\n"
	"\tpkgrel = 2\n"
	"\tepoch = 1\n"
	"\tarch = x86_64\n"
	"\tarch = aarch64\n"
	"\tmakedepends = cmake\n"
	"\tmakedepends_x86_64 = nasm\n"
	"\tcheckdepends = python-pytest\n"
	"\tdepends = glibc\n"
	"\tdepends = zlib>=1.2\n"
	"\tdepends_aarch64 = libarm\n"
	"\tsource = foo.tar.gz\n"
	"\tsha256sums = SKIP\n"
	"\n"
	"pkgname = foo\n"
	"\tprovides = foo-bin=1.2.3\n"
	"\n"
	"pkgname = foo-libs\n"
	"\tpkgdesc = Bibliotheken\n"
	"\tdepends = \n"
	"\tarch = any\n"
	"\n"
	"pkgname = foo-docs\n"
	"\tdepends = foo\n"
	"\tdepends_x86_64 = foo-x\n";

static int has(alpm_list_t *l, const char *s)
{
	return alpm_list_find_str(l, s) != NULL;
}

int main(void)
{
	char *err = NULL;
	aur_srcinfo_t *si = aur_srcinfo_parse(SI, &err);
	alpm_list_t *v;
	aur_si_pkg_t *foo, *libs, *docs;

	CHECK(si != NULL);
	if(!si) {
		printf("# %s\n", err);
		return CHECK_DONE();
	}
	CHECK_STR(si->pkgbase, "foo");
	CHECK_STR(si->version, "1:1.2.3-2");
	CHECK(alpm_list_count(si->pkgs) == 3);
	foo = aur_srcinfo_find_pkg(si, "foo");
	libs = aur_srcinfo_find_pkg(si, "foo-libs");
	docs = aur_srcinfo_find_pkg(si, "foo-docs");
	CHECK(foo && libs && docs);
	CHECK(aur_srcinfo_find_pkg(si, "bar") == NULL);

	v = aur_srcinfo_values(si, foo, AUR_FIELD_DEPENDS, "x86_64");
	CHECK(alpm_list_count(v) == 2 && has(v, "glibc") && has(v, "zlib>=1.2"));
	alpm_list_free(v);
	v = aur_srcinfo_values(si, foo, AUR_FIELD_DEPENDS, "aarch64");
	CHECK(alpm_list_count(v) == 3 && has(v, "libarm"));
	alpm_list_free(v);
	v = aur_srcinfo_values(si, libs, AUR_FIELD_DEPENDS, "x86_64");
	CHECK(v == NULL);
	v = aur_srcinfo_values(si, docs, AUR_FIELD_DEPENDS, "x86_64");
	CHECK(alpm_list_count(v) == 2 && has(v, "foo") && has(v, "foo-x"));
	alpm_list_free(v);
	v = aur_srcinfo_values(si, NULL, AUR_FIELD_MAKEDEPENDS, "x86_64");
	CHECK(alpm_list_count(v) == 2 && has(v, "cmake") && has(v, "nasm"));
	alpm_list_free(v);
	v = aur_srcinfo_values(si, NULL, AUR_FIELD_MAKEDEPENDS, "aarch64");
	CHECK(alpm_list_count(v) == 1);
	alpm_list_free(v);
	v = aur_srcinfo_values(si, NULL, AUR_FIELD_CHECKDEPENDS, "x86_64");
	CHECK(alpm_list_count(v) == 1 && has(v, "python-pytest"));
	alpm_list_free(v);
	v = aur_srcinfo_values(si, foo, AUR_FIELD_PROVIDES, "x86_64");
	CHECK(alpm_list_count(v) == 1 && has(v, "foo-bin=1.2.3"));
	alpm_list_free(v);
	v = aur_srcinfo_values(si, libs, AUR_FIELD_PROVIDES, "x86_64");
	CHECK(v == NULL);

	CHECK_STR(aur_srcinfo_pkgdesc(si, foo), "Basis-Beschreibung");
	CHECK_STR(aur_srcinfo_pkgdesc(si, libs), "Bibliotheken");
	CHECK(aur_srcinfo_supports_arch(si, foo, "x86_64"));
	CHECK(!aur_srcinfo_supports_arch(si, foo, "x86_64_musl"));
	CHECK(aur_srcinfo_supports_arch(si, libs, "x86_64_musl"));
	aur_srcinfo_free(si);

	/* musl-Variante: Architektur x86_64_musl (Unterstrich, damit makepkg
	 * depends_$CARCH als Variablennamen bilden kann) */
	si = aur_srcinfo_parse("pkgbase = m\npkgver = 1\npkgrel = 1\narch = x86_64\narch = x86_64_musl\n"
			"depends = zlib\ndepends_x86_64 = glibc-ding\ndepends_x86_64_musl = musl-fts\n"
			"makedepends_x86_64_musl = musl-bau\npkgname = m\n\npkgname = m-nurglibc\narch = x86_64\n", &err);
	CHECK(si != NULL);
	if(si) {
		aur_si_pkg_t *m = aur_srcinfo_find_pkg(si, "m"), *g = aur_srcinfo_find_pkg(si, "m-nurglibc");
		v = aur_srcinfo_values(si, m, AUR_FIELD_DEPENDS, "x86_64_musl");
		CHECK(alpm_list_count(v) == 2 && has(v, "zlib") && has(v, "musl-fts"));
		alpm_list_free(v);
		v = aur_srcinfo_values(si, m, AUR_FIELD_DEPENDS, "x86_64");
		CHECK(alpm_list_count(v) == 2 && has(v, "zlib") && has(v, "glibc-ding"));
		alpm_list_free(v);
		v = aur_srcinfo_values(si, m, AUR_FIELD_MAKEDEPENDS, "x86_64_musl");
		CHECK(alpm_list_count(v) == 1 && has(v, "musl-bau"));
		alpm_list_free(v);
		CHECK(aur_srcinfo_supports_arch(si, m, "x86_64_musl"));
		CHECK(!aur_srcinfo_supports_arch(si, g, "x86_64_musl"));
		CHECK(aur_srcinfo_supports_arch(si, g, "x86_64"));
		aur_srcinfo_free(si);
	}

	/* epoch 0 / fehlend */
	si = aur_srcinfo_parse("pkgbase = b\npkgver = 1\npkgrel = 1\nepoch = 0\npkgname = b\n", &err);
	CHECK(si && strcmp(si->version, "1-1") == 0);
	aur_srcinfo_free(si);

	/* Fehlerfälle */
	si = aur_srcinfo_parse("pkgname = x\n", &err);
	CHECK(si == NULL && err != NULL);
	free(err);
	si = aur_srcinfo_parse("pkgbase = x\npkgver = 1\npkgrel = 1\n", &err);
	CHECK(si == NULL && err != NULL);
	free(err);
	si = aur_srcinfo_parse("pkgbase = x\npkgver = 1\npkgrel = 1\npkgname = x\npkgname = x\n", &err);
	CHECK(si == NULL && err != NULL);
	free(err);
	si = aur_srcinfo_parse("pkgbase = x\nunsinn\n", &err);
	CHECK(si == NULL && err && strstr(err, "line 2"));
	free(err);
	si = aur_srcinfo_parse("pkgbase = x\npkgname = x\n", &err);
	CHECK(si == NULL && err != NULL);
	free(err);
	return CHECK_DONE();
}
